"proposal": {
    "capability": "deployment.set-probes",
    "target": {
        "group": "apps",
        "kind": "Deployment",
        "namespace": "finance",
        "name": "ledger",
        "uid": "uid-deployment-ledger"
    },
    "params": {
        "container": "app",
        "liveness": {
            "timeoutSeconds": 5
        }
    },
    "expected_effect": "Increase the liveness probe timeout to allow the app sufficient time to start before being terminated.",
    "rationale": "The app is taking longer than the current 1-second timeout to start, leading to liveness probe failures and restarts. Increasing the timeout to 5 seconds should allow the app to respond before the probe times out.",
